import Spreadsheet from "./components/spreadsheet"

export default function Page() {
  return (
    <div className="px-4 py-10 md:px-6 md:py-14 lg:py-16">
      <Spreadsheet />
    </div>
  )
}

"use client"

import { MousePointer2 } from "lucide-react"

import { cn } from "@/lib/utils"

import { GRID_DATA_ROW_REM } from "../lib/config"

type CursorProps = {
  x: number
  y: number
  pressed?: boolean
  /** Extra downward offset on top of half-row centering. */
  yNudgeRem?: number
  /** Data row track height — matches `gridTemplateRows` on compact layouts. */
  rowHeightRem?: number
  className?: string
}

export function Cursor({
  x,
  y,
  pressed,
  yNudgeRem = 0,
  rowHeightRem = GRID_DATA_ROW_REM,
  className,
}: CursorProps) {
  const rowCenterRem = rowHeightRem / 2 + yNudgeRem

  return (
    <MousePointer2
      aria-hidden
      strokeWidth={2}
      className={cn(
        "pointer-events-none absolute z-20 size-5",
        "fill-foreground stroke-background text-foreground",
        "[paint-order:stroke_fill]",
        "motion-safe:transition-[left,top,transform] motion-safe:duration-500 motion-safe:ease-out",
        className
      )}
      style={{
        left: `${x}%`,
        /* y = row top %; rem offset lands tip on row midpoint (+ optional nudge) */
        top: `calc(${y}% + ${rowCenterRem}rem)`,
        transform: `translate(-2px, -2px)${pressed ? " scale(0.92)" : ""}`,
      }}
    />
  )
}

"use client"

import { useEffect, useState } from "react"

import {
  EDIT_CELL,
  EDIT_FROM,
  EDIT_TO,
  EMPTY_TSM_ROW,
  GRID_METRICS_COMPACT,
  GRID_METRICS_DESKTOP,
  INITIAL_ROWS,
  PHASE_NEXT_MAP,
  SYNC_ROW,
  TIMING,
  TSM_DATA_ROW_INDEX,
  TSM_GL_FORMULA,
  TSM_MKT_FORMULA,
  VISIBLE_COLS,
  getSpreadsheetCursors,
  isTsmFormulaTypingPhase,
  isTsmTypingPhase,
  tsmPhaseColumn,
  tsmShowsCellChrome,
  tsmShowsFormula,
  type RowData,
  type SpreadsheetCursorPoint,
  type SpreadsheetPhase,
} from "../lib/config"

const TSM_VALUE_KEYS = ["account", "arr", "growth"] as const

/** Matches TIMING field cadence in config (`TSM_CHAR_MS`). */
const TSM_CHAR_MS = 132

function parseUsd(s: string): number {
  return Number.parseFloat(s.replace(/,/g, ""))
}

function parsePctSigned(s: string): number {
  return Number.parseFloat(s.trim().replace(/%/g, "")) / 100
}

function formatUsdMv(priceStr: string, qtyStr: string): string {
  const mv = Number.parseFloat(priceStr) * Number.parseInt(qtyStr, 10)
  return mv.toLocaleString("en-US", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })
}

function formatGainLossPct(decimal: number): string {
  const pct = decimal * 100
  const sign = pct >= 0 ? "+" : ""
  return `${sign}${pct.toFixed(1)}%`
}

export function useSpreadsheetAnimation(active = true, compact = false) {
  const gridMetrics = compact ? GRID_METRICS_COMPACT : GRID_METRICS_DESKTOP
  const spreadsheetCursor = getSpreadsheetCursors(gridMetrics)
  const [phase, setPhase] = useState<SpreadsheetPhase>("setup")
  const [typed, setTyped] = useState(0)
  const [pressed, setPressed] = useState(false)
  const [commitFlash, setCommitFlash] = useState(false)
  const [tsmDraft, setTsmDraft] = useState<RowData>(() => ({
    ...EMPTY_TSM_ROW,
  }))
  const [tsmFormulaTyping, setTsmFormulaTyping] = useState("")

  useEffect(() => {
    if (!active) {
      setPhase("setup")
      return
    }
    const t = setTimeout(() => setPhase(PHASE_NEXT_MAP[phase]), TIMING[phase])
    return () => clearTimeout(t)
  }, [active, phase])

  useEffect(() => {
    if (!active) return

    if (phase === "setup" || phase === "resetting") {
      setTyped(0)
      setPressed(false)
      setCommitFlash(false)
      setTsmDraft({ ...EMPTY_TSM_ROW })
      setTsmFormulaTyping("")
      return
    }

    if (phase === "tsmPrep") {
      setTyped(EDIT_TO.length)
      setTsmDraft({ ...EMPTY_TSM_ROW })
      setTsmFormulaTyping("")
      return
    }

    if (phase === "select") {
      setPressed(true)
      const t = setTimeout(() => setPressed(false), 180)
      return () => clearTimeout(t)
    }

    if (phase === "typing") {
      setTyped(0)
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 1; i <= EDIT_TO.length; i++) {
        timers.push(setTimeout(() => setTyped(i), 120 + i * 165))
      }
      return () => timers.forEach(clearTimeout)
    }

    if (phase === "commit") {
      setTyped(EDIT_TO.length)
      setCommitFlash(true)
      const t = setTimeout(() => setCommitFlash(false), 480)
      return () => clearTimeout(t)
    }

    if (phase === "tsmType0" || phase === "tsmType1" || phase === "tsmType2") {
      setTyped(EDIT_TO.length)
      setPressed(true)
      const unpress = setTimeout(() => setPressed(false), 180)
      setTsmFormulaTyping("")

      const colMap: Partial<Record<SpreadsheetPhase, number>> = {
        tsmType0: 0,
        tsmType1: 1,
        tsmType2: 2,
      }
      const col = colMap[phase] ?? 0
      const key = TSM_VALUE_KEYS[col]
      const target = SYNC_ROW[key]
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 1; i <= target.length; i++) {
        timers.push(
          setTimeout(() => {
            setTsmDraft((d) => ({
              ...d,
              [key]: target.slice(0, i),
            }))
          }, 155 + i * TSM_CHAR_MS),
        )
      }
      return () => {
        clearTimeout(unpress)
        timers.forEach(clearTimeout)
      }
    }

    if (phase === "tsmType3") {
      setTyped(EDIT_TO.length)
      setPressed(true)
      const unpress = setTimeout(() => setPressed(false), 180)
      setTsmFormulaTyping("")
      const target = TSM_MKT_FORMULA
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 1; i <= target.length; i++) {
        timers.push(
          setTimeout(() => {
            setTsmFormulaTyping(target.slice(0, i))
          }, 155 + i * TSM_CHAR_MS),
        )
      }
      const finalize = setTimeout(() => {
        setTsmDraft((d) => ({
          ...d,
          marketValue: SYNC_ROW.marketValue,
        }))
        setTsmFormulaTyping(target)
      }, 155 + target.length * TSM_CHAR_MS + 40)
      return () => {
        clearTimeout(unpress)
        timers.forEach(clearTimeout)
        clearTimeout(finalize)
      }
    }

    if (phase === "tsmType4") {
      setTyped(EDIT_TO.length)
      setPressed(true)
      const unpress = setTimeout(() => setPressed(false), 180)
      setTsmFormulaTyping("")
      const target = TSM_GL_FORMULA
      const timers: ReturnType<typeof setTimeout>[] = []
      for (let i = 1; i <= target.length; i++) {
        timers.push(
          setTimeout(() => {
            setTsmFormulaTyping(target.slice(0, i))
          }, 155 + i * TSM_CHAR_MS),
        )
      }
      const finalize = setTimeout(() => {
        setTsmDraft((d) => ({
          ...d,
          gainLoss: SYNC_ROW.gainLoss,
        }))
        setTsmFormulaTyping(target)
      }, 155 + target.length * TSM_CHAR_MS + 40)
      return () => {
        clearTimeout(unpress)
        timers.forEach(clearTimeout)
        clearTimeout(finalize)
      }
    }

    if (
      phase === "tsmMove0" ||
      phase === "tsmMove1" ||
      phase === "tsmMove2" ||
      phase === "tsmMove3" ||
      phase === "tsmMove4"
    ) {
      setTyped(EDIT_TO.length)
      if (phase === "tsmMove4") {
        setTsmFormulaTyping("")
      }
      return
    }

    if (phase === "holding") {
      setTyped(EDIT_TO.length)
      setTsmFormulaTyping("")
      setTsmDraft({ ...SYNC_ROW })
    }
  }, [active, phase])

  const isEditing = phase === "typing" || phase === "commit"

  const isSelected = phase === "select" || phase === "typing" || phase === "commit"

  const isTsmTyping = isTsmTypingPhase(phase)

  const editCommitted =
    phase === "commit" ||
    (phase.startsWith("tsm") && phase !== "resetting") ||
    phase === "holding"

  const editDisplay = isEditing ? EDIT_TO.slice(0, typed) : EDIT_FROM

  const baseRows = INITIAL_ROWS.map((row, i) => {
    if (i !== EDIT_CELL.row) return row
    if (!editCommitted) return row
    const impliedCost =
      parseUsd(row.marketValue) / (1 + parsePctSigned(row.gainLoss))
    const newMvNum = Number.parseFloat(EDIT_TO) * Number.parseInt(row.growth, 10)
    return {
      ...row,
      arr: EDIT_TO,
      marketValue: formatUsdMv(EDIT_TO, row.growth),
      gainLoss: formatGainLossPct((newMvNum - impliedCost) / impliedCost),
    }
  })

  const syncRowVisible =
    phase === "tsmPrep" ||
    phase.startsWith("tsmMove") ||
    phase.startsWith("tsmType") ||
    phase === "holding"

  const rows = syncRowVisible ? [...baseRows, tsmDraft] : baseRows

  const tsmCol = tsmPhaseColumn(phase)

  let cellRef: string
  let formulaPrefix: string
  let formulaValue: string

  if (tsmShowsFormula(phase)) {
    const sheetRow = TSM_DATA_ROW_INDEX + 2
    const col =
      phase === "tsmPrep" ? 0 : tsmCol !== null ? tsmCol : 0
    cellRef = `${VISIBLE_COLS[col]}${sheetRow}`
    const movePhase =
      phase === "tsmMove0" ||
      phase === "tsmMove1" ||
      phase === "tsmMove2" ||
      phase === "tsmMove3" ||
      phase === "tsmMove4"

    if (isTsmFormulaTypingPhase(phase)) {
      formulaPrefix = ""
      formulaValue = tsmFormulaTyping
    } else {
      const draftVals = [
        tsmDraft.account,
        tsmDraft.arr,
        tsmDraft.growth,
        tsmDraft.marketValue,
        tsmDraft.gainLoss,
      ] as const
      formulaPrefix = col === 1 ? "$" : ""
      formulaValue =
        phase === "tsmPrep" || movePhase ? "" : draftVals[col] ?? ""
    }
  } else {
    cellRef = `${VISIBLE_COLS[EDIT_CELL.col]}${EDIT_CELL.row + 2}`
    formulaPrefix = "$"
    formulaValue = isEditing ? editDisplay : EDIT_FROM
  }

  const showFormulaArea =
    isSelected || isEditing || tsmShowsFormula(phase)

  const cursorVisible =
    phase === "cursorMove" ||
    phase === "select" ||
    phase === "typing" ||
    phase === "commit" ||
    phase === "tsmPrep" ||
    phase.startsWith("tsmMove") ||
    phase.startsWith("tsmType")

  const cursor: SpreadsheetCursorPoint = (() => {
    if (phase === "cursorMove") return spreadsheetCursor.approach
    if (phase === "tsmPrep") return spreadsheetCursor.intelPrep
    if (tsmCol !== null) return spreadsheetCursor.tsmByCol[tsmCol]
    return spreadsheetCursor.cell
  })()

  let activeCol: number
  let activeRow: number

  if (tsmShowsCellChrome(phase) && tsmCol !== null) {
    activeCol = tsmCol
    activeRow = TSM_DATA_ROW_INDEX
  } else if (isSelected) {
    activeCol = EDIT_CELL.col
    activeRow = EDIT_CELL.row
  } else {
    activeCol = -1
    activeRow = -1
  }

  return {
    phase,
    pressed,
    isSelected,
    isEditing,
    isTsmTyping,
    commitFlash,
    syncRowVisible,
    tsmShowsSelectionChrome: tsmShowsCellChrome(phase),
    rows,
    cellRef,
    formulaPrefix,
    formulaValue,
    showFormulaArea,
    editDisplay,
    cursorVisible,
    cursor,
    activeCol,
    activeRow,
    tsmFocusCol: tsmCol,
  }
}

/**
 * Spreadsheet animation — semiconductor positions:
 * revise Intel price target → add TSM row (typed inputs + Excel-style formulas for value & return).
 */

export type SpreadsheetPhase =
  | "setup"
  | "cursorMove"
  | "select"
  | "typing"
  | "commit"
  | "tsmPrep"
  | "tsmMove0"
  | "tsmType0"
  | "tsmMove1"
  | "tsmType1"
  | "tsmMove2"
  | "tsmType2"
  | "tsmMove3"
  | "tsmType3"
  | "tsmMove4"
  | "tsmType4"
  | "holding"
  | "resetting"

const PHASE_NEXT: Record<SpreadsheetPhase, SpreadsheetPhase> = {
  setup: "cursorMove",
  cursorMove: "select",
  select: "typing",
  typing: "commit",
  commit: "tsmPrep",
  tsmPrep: "tsmMove0",
  tsmMove0: "tsmType0",
  tsmType0: "tsmMove1",
  tsmMove1: "tsmType1",
  tsmType1: "tsmMove2",
  tsmMove2: "tsmType2",
  tsmType2: "tsmMove3",
  tsmMove3: "tsmType3",
  tsmType3: "tsmMove4",
  tsmMove4: "tsmType4",
  tsmType4: "holding",
  holding: "resetting",
  resetting: "setup",
}

export const PHASE_NEXT_MAP = PHASE_NEXT

/** Character cadence + padding so phase timers outlive typing timers. */
const TSM_CHAR_MS = 132
const TSM_TYPE_PAD = 360

/** Visible data columns A–E; F–H stay blank in the mock. */
export const DATA_COLUMN_COUNT = 5 as const

/** Row shape — TSM row uses Excel row 5 in formulas (`B5`, `C5`, `D5`). */
export type RowData = {
  id: string
  account: string
  arr: string
  growth: string
  marketValue: string
  gainLoss: string
}

/** 0-based Intel row — price cell edited before TSM sync. */
export const EDIT_CELL = { row: 2, col: 1 }

/** Prior print → today’s price (Illustrative — align with `INITIAL_ROWS` INTC row.) */
export const EDIT_FROM = "107.95"
export const EDIT_TO = "108.77"

/**
 * Early/core: NVDA, INTC — larger % vs average cost.
 * Later tranches: AMD (underwater top-up), then TSM row (new starter line).
 */
export const INITIAL_ROWS: readonly RowData[] = [
  {
    id: "r1",
    account: "NVDA",
    arr: "225.32",
    growth: "38",
    marketValue: "8,562.16",
    gainLoss: "+245.3%",
  },
  {
    id: "r2",
    account: "AMD",
    arr: "424.10",
    growth: "12",
    marketValue: "5,089.20",
    gainLoss: "-7.8%",
  },
  {
    id: "r3",
    account: "INTC",
    arr: EDIT_FROM,
    growth: "85",
    marketValue: "9,175.75",
    gainLoss: "+52.1%",
  },
]

/** Newer TSM line — shares typed; value & % from formulas vs cost. */
export const SYNC_ROW: RowData = {
  id: "r4",
  account: "TSM",
  arr: "404.35",
  growth: "9",
  marketValue: "3,639.15",
  gainLoss: "+6.4%",
}

export const TSM_MKT_FORMULA = "=B5*C5" as const
/** Cost basis $3,420 — later buy; ~+6.4% vs `D5` at `404.35` × 9 shares. */
export const TSM_GL_FORMULA = "=(D5-3420)/3420" as const

function tsmValueTypeMs(len: number): number {
  return 170 + len * TSM_CHAR_MS + TSM_TYPE_PAD
}

function tsmFormulaTypeMs(formula: string): number {
  return 170 + formula.length * TSM_CHAR_MS + TSM_TYPE_PAD
}

export const TIMING: Record<SpreadsheetPhase, number> = {
  setup: 700,
  cursorMove: 900,
  select: 400,
  typing: 1400,
  commit: 600,
  tsmPrep: 400,
  tsmMove0: 660,
  tsmType0: tsmValueTypeMs(SYNC_ROW.account.length),
  tsmMove1: 640,
  tsmType1: tsmValueTypeMs(SYNC_ROW.arr.length),
  tsmMove2: 620,
  tsmType2: tsmValueTypeMs(SYNC_ROW.growth.length),
  tsmMove3: 620,
  tsmType3: tsmFormulaTypeMs(TSM_MKT_FORMULA),
  tsmMove4: 620,
  tsmType4: tsmFormulaTypeMs(TSM_GL_FORMULA),
  holding: 3000,
  resetting: 400,
}

export const VISIBLE_COLS = ["A", "B", "C", "D", "E", "F", "G", "H"] as const
/** Data columns only — used on narrow viewports (F–H stay blank on desktop). */
export const COMPACT_VISIBLE_COLS = VISIBLE_COLS.slice(0, DATA_COLUMN_COUNT)
export const VISIBLE_ROW_COUNT = 8

export type SpreadsheetGridMetrics = {
  dataColCount: number
  rowNumRem: number
  colLetterRowRem: number
  sheetHeaderRowRem: number
  dataRowRem: number
}

export const GRID_METRICS_DESKTOP: SpreadsheetGridMetrics = {
  dataColCount: VISIBLE_COLS.length,
  rowNumRem: 2.5,
  colLetterRowRem: 2.25,
  sheetHeaderRowRem: 2,
  dataRowRem: 2,
}

export const GRID_METRICS_COMPACT: SpreadsheetGridMetrics = {
  dataColCount: DATA_COLUMN_COUNT,
  rowNumRem: 1.75,
  colLetterRowRem: 1.5,
  sheetHeaderRowRem: 1.5,
  dataRowRem: 1.375,
}

/** Column labels rendered in sheet row 1 (A–E); F–H blank in UI. */
export const COLUMN_HEADERS = [
  "Symbol",
  "Price",
  "Quantity",
  "Market value",
  "Gain/Loss",
] as const

/** Appended sync row index in `rows` when visible (sheet row = index + 2). */
export const TSM_DATA_ROW_INDEX = 3

/** Empty placeholders until each cell is filled. */
export const EMPTY_TSM_ROW: RowData = {
  id: "r4",
  account: "",
  arr: "",
  growth: "",
  marketValue: "",
  gainLoss: "",
}

/** `max-w-6xl` sheet width — keeps cursor anchors aligned at default block size. */
const GRID_REF_WIDTH_REM = 72

/** Horizontal center of a 0-based data column as % of the grid overlay width. */
export function gridColumnCenterPercent(
  colIdx: number,
  metrics: SpreadsheetGridMetrics = GRID_METRICS_DESKTOP
): number {
  const { dataColCount, rowNumRem } = metrics
  const flexCol = (GRID_REF_WIDTH_REM - rowNumRem) / dataColCount
  const centerRem = rowNumRem + colIdx * flexCol + flexCol / 2
  return Math.round((centerRem / GRID_REF_WIDTH_REM) * 100)
}

/** Matches default desktop `gridTemplateRows` data tracks in spreadsheet.tsx. */
export const GRID_DATA_ROW_REM = GRID_METRICS_DESKTOP.dataRowRem

/** Extra downward tip nudge on the TSM row (reads high vs Intel row). */
export const TSM_CURSOR_Y_NUDGE_REM = 0.5

/** Vertical top of a 0-based data row as % of the grid overlay height. */
export function gridDataRowTopPercent(
  dataRowIdx: number,
  metrics: SpreadsheetGridMetrics = GRID_METRICS_DESKTOP
): number {
  const { colLetterRowRem, sheetHeaderRowRem, dataRowRem } = metrics
  const totalRem =
    colLetterRowRem +
    sheetHeaderRowRem +
    VISIBLE_ROW_COUNT * dataRowRem
  const topRem =
    colLetterRowRem + sheetHeaderRowRem + dataRowIdx * dataRowRem
  return Math.round((topRem / totalRem) * 100)
}

export type SpreadsheetCursorPoint = {
  x: number
  y: number
  /** Added to half-row centering in cursor.tsx (`rem`). */
  yNudgeRem?: number
}

/** Cursor anchors for the animated pointer — recomputed when column layout changes. */
export function getSpreadsheetCursors(
  metrics: SpreadsheetGridMetrics = GRID_METRICS_DESKTOP
) {
  const tsmRowY = gridDataRowTopPercent(TSM_DATA_ROW_INDEX, metrics)
  const editRowY = gridDataRowTopPercent(EDIT_CELL.row, metrics)
  const yNudge =
    metrics === GRID_METRICS_COMPACT ? TSM_CURSOR_Y_NUDGE_REM * 0.6 : TSM_CURSOR_Y_NUDGE_REM

  const tsmByCol: SpreadsheetCursorPoint[] = Array.from(
    { length: DATA_COLUMN_COUNT },
    (_, colIdx) => ({
      x: gridColumnCenterPercent(colIdx, metrics),
      y: tsmRowY,
      yNudgeRem: yNudge,
    })
  )

  return {
    approach: { x: 26, y: Math.max(editRowY - 8, 10) },
    cell: {
      x: gridColumnCenterPercent(EDIT_CELL.col, metrics),
      y: editRowY,
    },
    intelPrep: {
      x: gridColumnCenterPercent(4, metrics),
      y: editRowY,
    },
    tsmByCol,
  }
}

/** 0-based column during TSM move/type phases (null during prep / non-TSM). */
export function tsmPhaseColumn(phase: SpreadsheetPhase): number | null {
  const map: Partial<Record<SpreadsheetPhase, number>> = {
    tsmMove0: 0,
    tsmType0: 0,
    tsmMove1: 1,
    tsmType1: 1,
    tsmMove2: 2,
    tsmType2: 2,
    tsmMove3: 3,
    tsmType3: 3,
    tsmMove4: 4,
    tsmType4: 4,
  }
  return map[phase] ?? null
}

export function isTsmTypingPhase(phase: SpreadsheetPhase): boolean {
  return (
    phase === "tsmType0" ||
    phase === "tsmType1" ||
    phase === "tsmType2" ||
    phase === "tsmType3" ||
    phase === "tsmType4"
  )
}

/** True while a formula is being “typed” in the formula bar (mkt / G·L columns). */
export function isTsmFormulaTypingPhase(phase: SpreadsheetPhase): boolean {
  return phase === "tsmType3" || phase === "tsmType4"
}

/** Selection chrome on the active TSM cell (move + type). */
export function tsmShowsCellChrome(phase: SpreadsheetPhase): boolean {
  return tsmPhaseColumn(phase) !== null
}

/** Formula bar reflects TSM activity (prep shows destination A5 empty). */
export function tsmShowsFormula(phase: SpreadsheetPhase): boolean {
  return (
    phase === "tsmPrep" ||
    phase === "tsmMove0" ||
    phase === "tsmType0" ||
    phase === "tsmMove1" ||
    phase === "tsmType1" ||
    phase === "tsmMove2" ||
    phase === "tsmType2" ||
    phase === "tsmMove3" ||
    phase === "tsmType3" ||
    phase === "tsmMove4" ||
    phase === "tsmType4"
  )
}

/** Desktop cursor layout (default export for static references). */
export const SPREADSHEET_CURSOR = getSpreadsheetCursors(GRID_METRICS_DESKTOP)
export const TSM_CURSOR_BY_COL = SPREADSHEET_CURSOR.tsmByCol

/* spreadsheet — theme tokens, commit flash, caret blink */

.ss-root {
  --ss-shell-bg: #ffffff;
  --ss-border: #dadce0;
  --ss-shadow: 0 1px 2px rgb(60 64 67 / 0.3), 0 2px 6px 2px rgb(60 64 67 / 0.15);
  --ss-formula-bg: #ffffff;
  --ss-formula-border: #e0e0e0;
  --ss-name-box-fg: #3c4043;
  --ss-name-box-border: #dadce0;
  --ss-fx-fg: #70757a;
  --ss-grid-bg: #ffffff;
  --ss-header-bg: #f8f9fa;
  --ss-header-fg: #70757a;
  --ss-header-active: #d2e3fc;
  --ss-grid-line: #e0e0e0;
  --ss-cell-fg: #3c4043;
  --ss-cell-muted: #70757a;
  --ss-selection: #1a73e8;
  --ss-selection-fill: #ffffff;
  --ss-commit-flash: rgb(26 115 232 / 0.1);
  --ss-caret: #3c4043;
  --ss-sheet-bar-bg: #f8f9fa;
  --ss-sheet-bar-border: #dadce0;
  --ss-sheet-bar-icon: #5f6368;
  --ss-sheet-tab-bg: #e8f0fe;
  --ss-sheet-tab-fg: #1a73e8;
  /* Hero-scale type — readable inside max-w-6xl layouts */
  --ss-font-chrome: 0.8125rem;
  --ss-font-col-hdr: 0.6875rem;
  --ss-font-data: 0.75rem;
  --ss-font-tab: 0.75rem;
  /* matches `gridTemplateRows` data tracks in spreadsheet.tsx */
  --ss-grid-data-row-h: 2rem;
}

/* Narrow viewports: tighter chrome (grid columns A–E only — set in spreadsheet.tsx) */
.ss-root--compact {
  --ss-font-chrome: 0.6875rem;
  --ss-font-col-hdr: 0.5625rem;
  --ss-font-data: 0.625rem;
  --ss-font-tab: 0.6875rem;
  --ss-grid-data-row-h: 1.375rem;
}

.ss-root--compact .ss-cell-inner {
  padding-inline: 0.375rem;
}

.ss-font-chrome {
  font-size: var(--ss-font-chrome);
  line-height: 1.2;
}

.ss-font-col-hdr {
  font-size: var(--ss-font-col-hdr);
  line-height: 1.2;
}

.ss-font-data {
  font-size: var(--ss-font-data);
  line-height: 1.2;
}

.ss-font-tab {
  font-size: var(--ss-font-tab);
  line-height: 1.2;
}

.dark .ss-root {
  --ss-shell-bg: #202124;
  --ss-border: #5f6368;
  --ss-shadow: 0 1px 3px rgb(0 0 0 / 0.4), 0 4px 12px rgb(0 0 0 / 0.35);
  --ss-formula-bg: #202124;
  --ss-formula-border: #5f6368;
  --ss-name-box-fg: #e8eaed;
  --ss-name-box-border: #5f6368;
  --ss-fx-fg: #9aa0a6;
  --ss-grid-bg: #202124;
  --ss-header-bg: #292a2d;
  --ss-header-fg: #9aa0a6;
  --ss-header-active: #394457;
  --ss-grid-line: #3c4043;
  --ss-cell-fg: #e8eaed;
  --ss-cell-muted: #9aa0a6;
  --ss-selection: #8ab4f8;
  --ss-selection-fill: #202124;
  --ss-commit-flash: rgb(138 180 248 / 0.14);
  --ss-caret: #e8eaed;
  --ss-sheet-bar-bg: #292a2d;
  --ss-sheet-bar-border: #5f6368;
  --ss-sheet-bar-icon: #9aa0a6;
  --ss-sheet-tab-bg: #394457;
  --ss-sheet-tab-fg: #8ab4f8;
}

.ss-cell--commit-flash .ss-cell-inner {
  animation: ss-commit-flash 0.5s ease-out both;
}

@keyframes ss-commit-flash {
  0% {
    background-color: var(--ss-commit-flash);
  }
  100% {
    background-color: var(--ss-grid-bg);
  }
}

.ss-caret {
  animation: ss-caret-blink 1.1s step-start infinite;
}

@keyframes ss-caret-blink {
  0%,
  49.9% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}
